package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.HardwareMap;
import com.qualcomm.robotcore.util.ElapsedTime;

/**
 * Two-position (UP / DOWN) linear slide with a PID controller.
 * Call setPosition() to pick a target, then update() every loop.
 * The slides must be fully lowered at init, because the encoder is zeroed there.
 */
public class LinearSlide {
    public enum Position {UP, DOWN}

    // Tune these for your robot (encoder ticks and motor power)
    private static final int UP_TICKS = 500; // TODO: Use OP Mode to find value
    private static final int DOWN_TICKS = 0; // TODO: Use OP Mode to find value
    private static final int TOLERANCE = 10; // TODO: Change if slide position is out of range
    private static final double KP = 0.003, KI = 0, KD = 0; // TODO: Use OP Mode to find value
    private static final double HOLD_POWER = 0.15; // Power to hold UP against gravity & OP Mode to Tune

    private final DcMotor motor;
    private Position target = Position.DOWN; // Setting current state of motor based on enum
    private boolean active = false;

    private final ElapsedTime timer = new ElapsedTime();
    private double integral, lastError;

    public LinearSlide(HardwareMap hardwareMap) {
        motor = hardwareMap.get(DcMotor.class, "slideMotor");
        motor.setMode(DcMotor.RunMode.STOP_AND_RESET_ENCODER);
        motor.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER);
        motor.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.FLOAT);
    }

    public void setPosition(Position position) {
        target = position;
        integral = 0;
        lastError = 0;
        timer.reset();
        active = true;
    }

    /**
     * Runs the controller. Call once every loop.
     */
    public void update() {
        if (!active) return;

        double error = ticks(target) - motor.getCurrentPosition();
        double dt = Math.max(timer.seconds(), 1e-3);
        timer.reset();

        integral += error * dt;
        double power = KP * error + KI * integral + KD * (error - lastError) / dt;
        lastError = error;

        if (target == Position.UP) power += HOLD_POWER;
        motor.setPower(Math.max(-1, Math.min(1, power)));
    }

    public boolean isAtPosition() {
        return Math.abs(ticks(target) - motor.getCurrentPosition()) <= TOLERANCE;
    }

    /**
     * Cuts power so the slides float down under gravity.
     */
    public void stop() {
        active = false;
        motor.setPower(0);
    }

    private int ticks(Position p) {
        return p == Position.UP ? UP_TICKS : DOWN_TICKS;
    }
}

package org.firstinspires.ftc.teamcode.testopmodes;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;

import org.firstinspires.ftc.teamcode.subsystems.LinearSlide;

@TeleOp(name = "Linear Slide Tuner", group = "LinearSlide")
public class LinearSlideTuning extends LinearOpMode {
    @Override
    public void runOpMode() throws InterruptedException {
        LinearSlide slide = new LinearSlide(hardwareMap);

        waitForStart();
        while (opModeIsActive()) {
            // P: dpad left / right
            if (gamepad2.dpadRightWasPressed()) slide.kP += 0.0001;
            if (gamepad2.dpadLeftWasPressed()) slide.kP -= 0.0001;

            // I: dpad up / down
            if (gamepad2.dpadUpWasPressed()) slide.kI += 0.000001;
            if (gamepad2.dpadDownWasPressed()) slide.kI -= 0.000001;

            // D: B up / X down
            if (gamepad2.bWasPressed()) slide.kD += 0.0001;
            if (gamepad2.xWasPressed()) slide.kD -= 0.0001;

            // F (hold power): Y up / A down
            if (gamepad2.yWasPressed()) slide.holdPower += 0.001;
            if (gamepad2.aWasPressed()) slide.holdPower -= 0.001;

            // Move slide: left bumper = UP, right bumper = DOWN
            if (gamepad1.leftBumperWasPressed()) slide.setPosition(LinearSlide.Position.UP);
            if (gamepad1.rightBumperWasPressed()) slide.setPosition(LinearSlide.Position.DOWN);

            // Cut power so you can move the slide by hand and read the ticks
            if (gamepad1.aWasPressed()) slide.stop();

            slide.update();

            telemetry.addData("P", "%.6f", slide.kP);
            telemetry.addData("I", "%.10f", slide.kI);
            telemetry.addData("D", "%.6f", slide.kD);
            telemetry.addData("F (hold power)", "%.4f", slide.holdPower);
            telemetry.addData("Target", slide.getTarget());
            telemetry.addData("Ticks", slide.getPositionTicks());
            telemetry.addData("At position", slide.isAtPosition());
            telemetry.update();
        }
    }
}

package org.firstinspires.ftc.teamcode.testopmodes;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;

import org.firstinspires.ftc.teamcode.subsystems.LinearSlide;

@TeleOp(name = "Linear Slide Test", group = "LinearSlide")
public class LinearSlideTest extends LinearOpMode {
    @Override
    public void runOpMode() throws InterruptedException {
        LinearSlide slide = new LinearSlide(hardwareMap);

        waitForStart();
        while (opModeIsActive()) {
            if (gamepad1.leftBumperWasPressed()) {
                slide.setPosition(LinearSlide.Position.UP);
            }
            if (gamepad1.rightBumperWasPressed()) {
                slide.setPosition(LinearSlide.Position.DOWN);
            }

            slide.update();

            telemetry.addData("Target (UP/DOWN)", slide.getTarget());
            telemetry.addData("Ticks", slide.getPositionTicks());
            telemetry.addData("At position", slide.isAtPosition());
            telemetry.update();
        }
    }
}
